const root=document.documentElement;
const progress=document.querySelector('.progress');
const menu=document.querySelector('.menu');
const panel=document.querySelector('.mobile-panel');
const favicon=document.querySelector('#favicon');
const themeMeta=document.querySelector('meta[name="theme-color"]');
const themes={green:{accent:'#d9ff3f',deep:'#171c00',file:'g.png'},purple:{accent:'#a87cff',deep:'#211535',file:'p.png'},red:{accent:'#ff6b6b',deep:'#260f12',file:'r.png'},blue:{accent:'#168cff',deep:'#071a2b',file:'b.png'}};
function setTheme(name,save=true){const t=themes[name]||themes.green;root.style.setProperty('--accent',t.accent);root.style.setProperty('--accent-deep',t.deep);favicon.setAttribute('href',t.file);if(themeMeta)themeMeta.setAttribute('content',t.accent);document.querySelectorAll('.color').forEach(b=>b.classList.toggle('active',b.dataset.color===name));if(save)localStorage.setItem('faisal-theme',name)}
setTheme(localStorage.getItem('faisal-theme')||'green',false);
document.querySelectorAll('.color').forEach(b=>b.addEventListener('click',()=>setTheme(b.dataset.color)));
if(menu){menu.addEventListener('click',()=>{const open=panel.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.classList.toggle('open',open)})}
document.querySelectorAll('.mobile-nav a').forEach(a=>a.addEventListener('click',()=>{panel.classList.remove('open');menu?.setAttribute('aria-expanded','false');menu?.classList.remove('open')}));
function updateProgress(){const max=document.documentElement.scrollHeight-window.innerHeight;progress.style.width=max>0?`${(window.scrollY/max)*100}%`:'0%'}
window.addEventListener('scroll',updateProgress,{passive:true});updateProgress();
document.documentElement.classList.add('js-ready');
const reveal=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');reveal.unobserve(e.target)}}),{threshold:.04,rootMargin:'0px 0px -5% 0px'});
document.querySelectorAll('.reveal').forEach(e=>{if(e.getBoundingClientRect().top<window.innerHeight*1.05)e.classList.add('visible');reveal.observe(e)});
const sections=[...document.querySelectorAll('main section[id]')];
function updateActive(){let current='home',best=Infinity;const marker=window.scrollY+window.innerHeight*.25;sections.forEach(s=>{const d=Math.abs(s.offsetTop-marker);if(d<best){best=d;current=s.id}});document.querySelectorAll('.desktop-nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+current))}
window.addEventListener('scroll',updateActive,{passive:true});window.addEventListener('resize',updateActive);updateActive();
const glow=document.querySelector('.cursor-glow');window.addEventListener('pointermove',e=>{if(glow){glow.style.left=e.clientX+'px';glow.style.top=e.clientY+'px'}},{passive:true});
document.querySelectorAll('.project').forEach(card=>{card.addEventListener('pointermove',e=>{if(matchMedia('(pointer: coarse)').matches)return;const r=card.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;const rx=Math.max(-2.2,Math.min(2.2,-((y/r.height)-.5)*4.4)),ry=Math.max(-2.2,Math.min(2.2,((x/r.width)-.5)*4.4));card.style.transform=`perspective(1200px) rotateX(${rx}deg) rotateY(${ry}deg) translateY(-2px)`});card.addEventListener('pointerleave',()=>card.style.transform='')});
window.addEventListener('pageshow',()=>{document.querySelectorAll('.reveal').forEach(e=>{if(e.getBoundingClientRect().top<innerHeight*.9)e.classList.add('visible')});updateProgress();updateActive()});
document.getElementById('year').textContent=new Date().getFullYear();
// PyPI icon is embedded here so the portfolio needs no separate PyPI asset.
const PYPI_ICON_DATA = "data:image/svg+xml;base64,";
document.querySelectorAll('[data-pypi-icon]').forEach(img => img.src = PYPI_ICON_DATA);
